import CoreLocation
import Foundation

/// One train line's platforms in travel order, from `train_lines.json` (generated by tools/gtfs_build.py, the same
/// sequences as the firmware's `kTrainLines`). Runs overlap where a train turns at the Loop (a Brown train bound for
/// Kimball starts its run at Diversey, before the Loop), so `VehiclePlace` joins them stop by stop.
public struct TrainRun: Decodable, Sendable {
    public struct Stop: Decodable, Sendable {
        public let id: String     // platform ID
        public let name: String
    }
    public let route: String
    public let dir: String
    public let stops: [Stop]

    public static func decode(_ data: Data) throws -> [TrainRun] { try JSONDecoder().decode([TrainRun].self, from: data) }
}

/// Where a train or bus is along its line, in plain words (F6): "At Fullerton", "Between Belmont and Wellington,
/// 3 stops away". `away` counts the stops it still has to reach up to and including the open stop; nil when the open
/// stop isn't ahead of it (the other direction, another branch, past where it ends, or already passed).
public struct VehiclePlace: Equatable, Sendable {
    public enum Spot: Equatable, Sendable {
        case at(String)
        case between(String, String)
        case approaching(String)   // heading for the first stop of a line whose stop before it isn't known
    }

    public let spot: Spot
    public let away: Int?

    /// Closer than this to a stop counts as at it: a train platform is about 150 m long, buses stop at most a few
    /// bus lengths from the pole.
    public static let atStationMeters: Double = 150
    public static let atBusStopFeet: Double = 200

    public init(spot: Spot, away: Int?) { (self.spot, self.away) = (spot, away) }

    public var toward: Bool { away != nil }

    public var text: String {
        let place = switch spot {
        case .at(let s): "At \(Self.short(s))"
        case .between(let a, let b): "Between \(Self.short(a)) and \(Self.short(b))"
        case .approaching(let s): "Approaching \(Self.short(s))"
        }
        guard let away, away > 0 else { return place }
        return "\(place), \(away) \(away == 1 ? "stop" : "stops") away"
    }

    /// "Harlem (Blue - O'Hare Branch)" reads "Harlem": the line is already on screen.
    static func short(_ name: String) -> String {
        name.range(of: " (").map { String(name[..<$0.lowerBound]) } ?? name
    }

    /// Where the firmware's sequences cut one trip in two (each piece keeps only stops every train on it reaches):
    /// the Purple Express between Howard and Wilson both ways, and Green's south branches off Garfield.
    static let joins: [String: [(String, String)]] = [
        "P": [("30176", "30385"), ("30386", "30175")],
        "G": [("30100", "30217"), ("30100", "30184"), ("30183", "30099")],
    ]

    /// A train by its next stop (ttpositions `nextStpId`), walking its line's platforms forward to `target`.
    /// `coordinate` gives a platform's station, to tell "at" from "between". When the train's destination is a stop
    /// on the line, it goes no further, and only stops on the way there count (Cottage Grove trains never reach
    /// Ashland/63rd; a Purple shuttle ends at Howard).
    public static func train(_ v: Vehicle, route: String, target: String?, runs: [TrainRun],
                             coordinate: (String) -> CLLocationCoordinate2D?) -> VehiclePlace? {
        var next: [String: Set<String>] = [:], prev: [String: Set<String>] = [:], names: [String: String] = [:]
        func join(_ a: String, _ b: String) { next[a, default: []].insert(b); prev[b, default: []].insert(a) }
        for run in runs where run.route == route {
            for s in run.stops { names[s.id] = s.name }
            for (a, b) in zip(run.stops, run.stops.dropFirst()) { join(a.id, b.id) }
        }
        for (a, b) in joins[route] ?? [] where names[a] != nil && names[b] != nil { join(a, b) }

        let n = v.nextStopID
        guard let nName = names[n] else { return nil }
        let here = CLLocationCoordinate2D(latitude: v.lat, longitude: v.lon)
        func meters(_ id: String) -> Double { coordinate(id).map { StopIndex.meters(here, $0) } ?? .infinity }
        let ends = Set(names.filter { short($0.value) == v.dest }.keys)
        /// Stops from `from` to the nearest stop passing `goal`, never past where the train ends.
        func steps(_ from: String, to goal: (String) -> Bool) -> Int? {
            var seen: Set = [from], layer = [from], count = 0
            while !layer.isEmpty {
                if layer.contains(where: goal) { return count }
                layer = layer.filter { !ends.contains($0) }.flatMap { next[$0] ?? [] }.filter { seen.insert($0).inserted }
                count += 1
            }
            return nil
        }

        let p = prev[n]?.min { meters($0) < meters($1) }   // Garfield northbound has two: the nearer one
        let atNext = meters(n) < atStationMeters
        let atPrev = !atNext && p.map { meters($0) < atStationMeters } == true
        let spot: Spot = atNext ? .at(nName)
            : p.map { atPrev ? .at(names[$0]!) : .between(names[$0]!, nName) } ?? .approaching(nName)

        guard let target else { return VehiclePlace(spot: spot, away: nil) }
        if atPrev, p == target { return VehiclePlace(spot: spot, away: 0) }   // still at the stop it just served
        let onTheWay = ends.isEmpty || steps(target, to: ends.contains) != nil
        let away = onTheWay ? steps(n, to: { $0 == target }).map { $0 + (atNext ? 0 : 1) } : nil
        return VehiclePlace(spot: spot, away: away)
    }

    /// A bus by its distance along its pattern (getvehicles `pid` and `pdist`, getpatterns' stops).
    public static func bus(_ v: Vehicle, target: String?, patterns: [Pattern]) -> VehiclePlace? {
        guard let pid = v.pid, let d = v.pdist, let pattern = patterns.first(where: { $0.pid == pid }) else { return nil }
        let stops = pattern.points.filter { $0.stopID != nil }
        guard !stops.isEmpty else { return nil }
        let names = stops.map { $0.stopName ?? "" }, ids = stops.map { $0.stopID ?? "" }
        let n = stops.firstIndex { $0.pdist > d } ?? stops.count   // the next stop
        // At stop i, or between stops i - 1 and i (heading for i).
        let (i, at): (Int, Bool)
        if n == stops.count { (i, at) = (n - 1, true) }
        else if n == 0 || stops[n].pdist - d <= atBusStopFeet { (i, at) = (n, true) }
        else if d - stops[n - 1].pdist <= atBusStopFeet { (i, at) = (n - 1, true) }
        else { (i, at) = (n, false) }
        // The first time the pattern reaches the open stop from here; heading for stop i, i itself is 1 stop away.
        let t = target.flatMap { id in ids.indices.dropFirst(i).first { ids[$0] == id } }
        return VehiclePlace(spot: at ? .at(names[i]) : .between(names[i - 1], names[i]), away: t.map { $0 - (at ? i : i - 1) })
    }
}

/// What the page can honestly say about the focused vehicle (F6): found, or why its position isn't shown.
public enum VehicleFocus: Equatable, Sendable {
    case finding        // no positions fetched yet
    case found(Vehicle)
    case notYet         // not in the feed since it was focused (a scheduled train that hasn't left yet)
    case lost           // it was in the feed and dropped out
    case unavailable    // the positions feed has been failing

    /// `vehicles` is the last good fetch (nil before one lands, or once failures make it too old to show);
    /// `seen` is whether a fetch since the focus contained it.
    public static func of(_ id: String, vehicles: [Vehicle]?, seen: Bool, failing: Bool) -> VehicleFocus {
        guard let vehicles else { return failing ? .unavailable : .finding }
        if let v = vehicles.first(where: { $0.id == id }) { return .found(v) }
        return seen ? .lost : .notYet
    }

    /// The page's line for a focus without a position; nil when found (the place says it).
    public func text(bus: Bool) -> String? {
        let it = bus ? "bus" : "train"
        return switch self {
        case .found: nil
        case .finding: "Finding this \(it)…"
        case .notYet: "This \(it) isn't sharing its position yet"
        case .lost: "Lost this \(it): it stopped sharing its position"
        case .unavailable: "Can't get \(it) positions right now"
        }
    }
}

extension Prediction {
    /// The arrival's train or bus in a positions feed: Train Tracker's run number or Bus Tracker's vehicle ID.
    public func vehicle(in vehicles: [Vehicle]) -> Vehicle? {
        guard let vehicle else { return nil }
        return vehicles.first { $0.id == vehicle }
    }
}
